import{_ as t,o,c as e,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"2018-May-29 :: Ceph Code Walkthrough: BlueStore part 1","description":"","frontmatter":{"title":"2018-May-29 :: Ceph Code Walkthrough: BlueStore part 1","date":"2018-05-30T00:00:00.000Z","updated":"2018-05-30T00:00:00.000Z","tags":["Ceph","BlueStore","数据存储","分布式存储","RocksDB"],"categories":["Ceph 代码解析","视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/2018-May-29_-_-_Ceph_Code_Walkthrough_-_BlueStore_part_1.md","filePath":"posts/2018/2018-May-29_-_-_Ceph_Code_Walkthrough_-_BlueStore_part_1.md","lastUpdated":1780459816000}'),i={name:"posts/2018/2018-May-29_-_-_Ceph_Code_Walkthrough_-_BlueStore_part_1.md"};function a(s,l,u,n,_,p){return o(),e("div",null,[...l[0]||(l[0]=[r('<h2 id="改进后的中文总结内容" tabindex="-1">改进后的中文总结内容 <a class="header-anchor" href="#改进后的中文总结内容" aria-label="Permalink to &quot;改进后的中文总结内容&quot;">​</a></h2><h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题</strong>： BlueStore 源码解析</p><p><strong>参会人员</strong>： 未知</p><p><strong>会议时间</strong>： 未知</p><p><strong>会议地点</strong>： 未知</p><p><strong>会议内容</strong>：</p><ul><li><strong>BlueStore 简介</strong>： <ul><li>BlueStore 是 Ceph 对象存储后端，直接处理对象存储接口，使用 RocksDB 作为元数据存储，并使用 BlueFS 作为文件系统。</li><li>BlueStore 具备两个主要操作类别：同步阻塞的读操作和基于事务的写操作。</li></ul></li><li><strong>BlueFS</strong>： <ul><li>BlueFS 是 BlueStore 的文件系统实现，直接使用原始块设备，并通过 RocksDB 的文件系统接口存储所有文件。</li><li>BlueFS 提供基本的文件操作，如创建、读取、写入和删除文件。</li></ul></li><li><strong>块设备接口</strong>： <ul><li>块设备接口提供了对块设备的低级抽象，支持读取、写入、预读和预写操作。</li><li>BlueStore 使用内核设备作为块设备接口的实现，直接与内核的异步 I/O 接口交互。</li></ul></li><li><strong>BlueStore 的分配器</strong>： <ul><li>分配器负责决定磁盘上哪些部分可用。</li><li>BlueStore 使用两种分配器实现：Stupid Allocator 和 Bitmap Allocator。</li><li>Bitmap Allocator 更高效、更确定，且内存占用更少。</li></ul></li><li><strong>BlueStore 的磁盘结构</strong>： <ul><li>BlueStore 使用多种类型来表示磁盘结构，包括块设备标签、对象、集合、范围和 blob。</li><li>块设备标签包含有关设备的信息，如 OSD 的 UID、大小、创建时间和描述。</li><li>对象是磁盘上存储的数据单元，由 blob 组成。</li><li>集合是类似于目录的对象组。</li><li>范围是对象的一部分，由 blob 表示。</li><li>Blob 是磁盘上存储数据的物理区域。</li></ul></li><li><strong>读取路径</strong>： <ul><li>读取路径首先查找对象的元数据，然后从 RocksDB 中读取 blob。</li><li>如果 blob 是压缩的，则需要解压缩它。</li><li>最后，将读取的数据组装成最终结果。</li></ul></li></ul><p><strong>行动计划</strong>：</p><ul><li>将本次会议内容录制并发布到 YouTube。</li><li>计划进行后续会议，深入探讨写入路径的实现。</li></ul><p><strong>备注</strong>：</p><ul><li>会议中提到了许多计算机科学/ceph 领域的英文关键词，如对象存储、RocksDB、BlueFS、块设备接口、分配器、磁盘结构、读取路径等。</li><li>会议内容涵盖了 BlueStore 的主要功能和实现细节，对于想要了解 BlueStore 的研发人员来说非常有价值。</li></ul><h2 id="改进点" tabindex="-1">改进点 <a class="header-anchor" href="#改进点" aria-label="Permalink to &quot;改进点&quot;">​</a></h2><ol><li><strong>准确性</strong>： 确保总结准确反映了原始内容的要点，包括 BlueStore 的功能、BlueFS 的作用、块设备接口的实现细节等。</li><li><strong>关键词保留</strong>： 在总结中保留了相关的 Ceph 和计算机科学领域的英文关键词。</li><li><strong>完整性</strong>： 总结了会议的关键细节、讨论的主要议题、决定的事项以及后续的行动计划。</li></ol>',14)])])}const B=t(i,[["render",a]]);export{h as __pageData,B as default};
